// Shared PDF layout for MEDIUM reports: A4, MEDIUM header, brand-blue headings,
// footer "Generated by MEDIUM Admin on <date, Maldives time> · page n of m".
import PDFDocument from 'pdfkit';

export const BRAND = '#12229D';
export const INK = '#101828';
export const MUTED = '#667085';
const MARGIN = 50;
// Fixed month names: some ICU versions write "Sept"
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

const WHEN = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Indian/Maldives',
  day: 'numeric',
  month: 'numeric',
  year: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
  hour12: false,
});

// "13 Oct 2026, 09:00" in Maldives time
export function maldivesTime(date: Date): string {
  const p = Object.fromEntries(WHEN.formatToParts(date).map((x) => [x.type, x.value]));
  return `${Number(p.day)} ${MONTHS[Number(p.month) - 1]} ${p.year}, ${p.hour}:${p.minute}`;
}

// "2026-09-01" → "1 Sep 2026"
export function day(iso: string): string {
  const [y, m, d] = iso.split('-').map(Number);
  return `${d} ${MONTHS[m - 1]} ${y}`;
}

export type Doc = PDFKit.PDFDocument;

// Builds a report: `draw` adds the content; header and numbered footers are added to every page
export function renderPdf(title: string, subtitle: string, now: Date, draw: (doc: Doc) => void): Promise<Buffer> {
  const doc = new PDFDocument({ size: 'A4', margin: MARGIN, bufferPages: true, info: { Title: title, Author: 'MEDIUM Events Pvt Ltd', Creator: 'MEDIUM Admin' } });
  const chunks: Buffer[] = [];
  doc.on('data', (c: Buffer) => chunks.push(c));
  const done = new Promise<Buffer>((resolve) => doc.on('end', () => resolve(Buffer.concat(chunks))));

  // Header: logo mark + wordmark, then the report title
  doc.rect(MARGIN, MARGIN, 26, 26).fill(BRAND);
  doc.fillColor('#FFFFFF').font('Helvetica-Bold').fontSize(15).text('M', MARGIN, MARGIN + 6, { width: 26, align: 'center' });
  doc.fillColor(INK).font('Helvetica-Bold').fontSize(13).text('MEDIUM Events', MARGIN + 36, MARGIN + 7);
  doc.moveDown(2.2);
  doc.x = MARGIN;
  doc.fillColor(BRAND).font('Helvetica-Bold').fontSize(20).text(title);
  if (subtitle) doc.fillColor(MUTED).font('Helvetica').fontSize(11).text(subtitle);
  doc.moveDown();
  doc.fillColor(INK).font('Helvetica').fontSize(10.5);

  draw(doc);

  const generated = `Generated by MEDIUM Admin on ${maldivesTime(now)} (Maldives time)`;
  const range = doc.bufferedPageRange();
  for (let i = range.start; i < range.start + range.count; i++) {
    doc.switchToPage(i);
    const bottom = doc.page.height - MARGIN + 15;
    doc.page.margins.bottom = 0;
    doc.fillColor(MUTED).font('Helvetica').fontSize(8.5).text(`${generated} · page ${i + 1} of ${range.count}`, MARGIN, bottom, { width: doc.page.width - MARGIN * 2, align: 'center' });
  }
  doc.end();
  return done;
}

export function heading(doc: Doc, text: string) {
  doc.moveDown(0.8);
  doc.x = MARGIN;
  doc.fillColor(BRAND).font('Helvetica-Bold').fontSize(13).text(text);
  doc.moveDown(0.3);
  doc.fillColor(INK).font('Helvetica').fontSize(10.5);
}

// "Label: value" lines, skipping empty values
export function facts(doc: Doc, rows: [string, string | number | null | undefined][]) {
  for (const [label, value] of rows) {
    if (value === null || value === undefined || value === '') continue;
    doc.x = MARGIN;
    doc.font('Helvetica-Bold').text(`${label}: `, { continued: true }).font('Helvetica').text(String(value));
  }
}

// A simple table; columns are [header, width, align]. Adds pages as needed and repeats the header.
export function table(doc: Doc, columns: [string, number, 'left' | 'right'][], rows: (string | number)[][], opts: { boldLast?: number } = {}) {
  const drawRow = (cells: (string | number)[], bold: boolean, color = INK) => {
    if (doc.y > doc.page.height - MARGIN - 40) {
      doc.addPage();
      drawRow(columns.map((c) => c[0]), true, BRAND);
    }
    const y = doc.y;
    let x = MARGIN;
    let height = 0;
    doc.font(bold ? 'Helvetica-Bold' : 'Helvetica').fontSize(9.5).fillColor(color);
    columns.forEach(([, width, align], i) => {
      const text = String(cells[i] ?? '');
      doc.text(text, x + 3, y + 4, { width: width - 6, align });
      height = Math.max(height, doc.heightOfString(text, { width: width - 6 }) + 8);
      x += width;
    });
    doc.moveTo(MARGIN, y + height).lineTo(x, y + height).strokeColor('#E4E7EC').lineWidth(0.5).stroke();
    doc.y = y + height;
  };
  drawRow(columns.map((c) => c[0]), true, BRAND);
  rows.forEach((row, i) => drawRow(row, i >= rows.length - (opts.boldLast ?? 0)));
  doc.x = MARGIN;
  doc.moveDown(0.5);
  doc.fillColor(INK).font('Helvetica').fontSize(10.5);
}
